const id=useProjectId(),route=useRoute(),router=useRouter(),store=useAipptEditorStore(),user=useUserStore(),project=ref<Project|null>(null),deck=ref<Deck|null>(null),selectedId=ref(''),blockId=ref<string|null>(null),tab=ref('content'),error=ref(''),loading=ref(false),busy=ref(false),zoom=ref(100),exportOpen=ref(false),present=ref(false),previewTree=ref<FlexContainer|null>(null),draftDialog=ref(false),draftText=ref(''),catalogReady=ref(false),filmstripOpen=ref(true),inspectorOpen=ref(true)
let loadGeneration=0,viewGeneration=0,selectionGeneration=0,refreshTimer:ReturnType<typeof setTimeout>|undefined,removeGuard:(()=>void)|undefined,alive=true,actionTail=Promise.resolve();type RequestCommand={key:string;body:Record<string,unknown>};const generationCommands=new Map<string,RequestCommand>(),retryCommands=new Map<string,RequestCommand>(),cancelCommands=new Map<string,RequestCommand>();const deckCommands=new Map<string,{revision:number;key:string;ids:string[]}>();const controllers=new Set<AbortController>(),themeQueues=store.themeQueues,themePanel=ref<InstanceType<typeof ThemePanel>|null>(null),themePreview=ref<ThemeDraft|null>(null)
const themeQueue=computed(()=>project.value?themeQueues.get(project.value.id):undefined),themeProject=computed(()=>project.value?{...project.value,...(themePreview.value?.project_id===project.value.id?{theme_id:themePreview.value.theme_id,theme_overrides:themePreview.value.theme_overrides}:themeQueue.value?.state.draft?{theme_id:themeQueue.value.state.draft.theme_id,theme_overrides:themeQueue.value.state.draft.theme_overrides}:{})}:null)
const canEdit=computed(()=>checkPermi(['aippt:slide:edit'])),canTheme=computed(()=>checkPermi(['aippt:theme:edit'])),canAI=computed(()=>checkPermi(['aippt:ai:edit'])),canImage=computed(()=>checkPermi(['aippt:image:upload']))
const generating=computed(()=>deck.value?.status==='generating'||project.value?.status==='generating'),official=computed(()=>deck.value?.slides.find(s=>s.id===selectedId.value)),queue=computed(()=>official.value?store.queues.get(id.value+':'+official.value.id):undefined),current=computed(()=>queue.value?.state.draft||queue.value?.state.slide||official.value),viewSlide=computed(()=>current.value?previewTree.value?{...current.value,layout_tree:previewTree.value}:current.value:null),selected=computed(()=>current.value?.blocks.find(b=>b.id===blockId.value)),theme=computed(()=>catalogReady.value&&project.value?resolveTheme(themeProject.value!.theme_id,themeProject.value!.theme_overrides as ThemeOverrides):null),disabled=computed(()=>!canEdit.value||busy.value||generating.value||queue.value?.state.status==='conflict'||queue.value?.state.status==='failed'),saveLabel=computed(()=>!queue.value?'':({saved:'已保存',saving:'保存中',failed:'保存失败',conflict:'版本冲突'}[queue.value.state.status])),parent=computed(()=>current.value?.layout_tree&&blockId.value?findLeafParent(current.value.layout_tree,blockId.value):null)
function commitSlide(slide:Slide){if(!deck.value)return;const at=deck.value.slides.findIndex(s=>s.id===slide.id);if(at>=0)deck.value.slides[at]=slide;else deck.value.slides.push(slide)}
async function load(full=true){const own=++loadGeneration,pid=id.value;if(!pid){error.value='缺少项目标识，请从列表重新打开';return}if(full)loading.value=true
 try{await ensureCatalog();const [p,d]=await Promise.all([api.project(pid),api.deck(pid)]);if(own!==loadGeneration||!alive)return;project.value=p;initThemeQueue(p).replaceServer(p);deck.value=d;catalogReady.value=true;if(d.status==='generating'&&!events.task.value)events.watch(pid,'deck');for(const s of d.slides)store.queue(pid,s,commitSlide);if(!d.slides.some(s=>s.id===selectedId.value))selectedId.value=d.slides[0]?.id||'';error.value=''}catch(e:any){if(own===loadGeneration)error.value=e.message||'读取演示文稿失败'}finally{if(own===loadGeneration)loading.value=false}}
