function blurEditing(){const active=document.activeElement;if(active instanceof HTMLElement&&active.isContentEditable)active.blur()}
function activeTarget(pid:string,own:number,sid?:string){return own===viewGeneration&&pid===id.value&&(!sid||sid===selectedId.value)}
function requireTarget(pid:string,own:number,sid?:string){if(!activeTarget(pid,own,sid))throw Object.assign(new Error('编辑目标已切换，请在当前项目页面重新操作'),{name:'AbortError'})}
async function flush(){const pid=id.value,own=viewGeneration;blurEditing();await nextTick();await themePanel.value?.flush();await store.flush(pid);await themeQueues.get(pid)?.flush();requireTarget(pid,own);const p=await api.project(pid);requireTarget(pid,own);project.value=p;if(deck.value)deck.value.deck_revision=p.deck_revision}
async function choose(sid:string){const pid=id.value,own=viewGeneration,selection=++selectionGeneration,q=queue.value;try{blurEditing();await nextTick();await q?.flush();if(!activeTarget(pid,own)||selection!==selectionGeneration)return;selectedId.value=sid;blockId.value=null;previewTree.value=null}catch(e:any){if(activeTarget(pid,own)&&selection===selectionGeneration){error.value=e.message;tab.value='content'}}}
function catchError(e:any){error.value=e?.message||'操作失败，内容已保留'}
function enqueue(intent:Parameters<NonNullable<typeof queue.value>['enqueue']>[0],draft?:Slide,history=true){const q=queue.value,pid=id.value,own=viewGeneration;if(!q||disabled.value)return Promise.reject(new Error('当前页面尚不可编辑'));return q.enqueue(intent,draft,history).catch(e=>{if(activeTarget(pid,own))catchError(e);throw e})}
function content(bid:string,commit:EditableBlockCommit){const pid=id.value;if(!current.value)return;const body=mergeBlockCommit(current.value,bid,commit);if(!body)return;const draft=cloneJson(current.value);draft.blocks=draft.blocks.map(b=>b.id===bid?{...b,...body,locked:true} as Block:b)
 void enqueue((s,c)=>{const latest=mergeBlockCommit(s,bid,commit);if(!latest)throw new Error('内容块已变化，请重新读取');return api.page(pid,s.id,'patch',`blocks/${bid}`,{...latest,revision:s.revision},c.idempotencyKey)},draft).catch(()=>{})}
function fullContent(body:Record<string,unknown>){const pid=id.value;if(!selected.value||!current.value)return;const bid=selected.value.id,draft=cloneJson(current.value);draft.blocks=draft.blocks.map(b=>b.id===bid?{...b,...body,locked:true} as Block:b);void enqueue((s,c)=>api.page(pid,s.id,'patch',`blocks/${bid}`,{...body,revision:s.revision},c.idempotencyKey),draft).catch(()=>{})}
function style(patch:Partial<BlockStyle>|null){const pid=id.value;if(!selected.value||!current.value)return;const bid=selected.value.id,draft=cloneJson(current.value);draft.blocks=draft.blocks.map(b=>b.id===bid?{...b,style:patch===null?null:patchStyle(b.style,patch)}:b);void enqueue((s,c)=>{const b=s.blocks.find(b=>b.id===bid);if(!b)throw new Error('块已不存在');return api.page(pid,s.id,'patch',`blocks/${bid}/style`,{revision:s.revision,style:patch===null?null:patchStyle(b.style,patch)},c.idempotencyKey)},draft).catch(()=>{})}
function layoutTree(tree:FlexContainer){const pid=id.value;if(!current.value)return;tree=cloneJson(tree);for(const leaf of iterLeaves(tree))delete leaf.rect_override;const draft={...cloneJson(current.value),layout_tree:tree};void enqueue((s,c)=>api.page(pid,s.id,'put','flex-layout',{revision:s.revision,layout_tree:tree},c.idempotencyKey),draft).catch(()=>{})}
async function pageAction(action:'insert'|'duplicate'|'remove'|'order',ids?:string[]){const pid=id.value,own=viewGeneration,chosen=selectedId.value,ordered=cloneJson(ids||[]),key=pid+':'+action+':'+chosen+':'+JSON.stringify(ordered);actionTail=actionTail.then(async()=>{if(!activeTarget(pid,own))return;busy.value=true;try{await flush();requireTarget(pid,own,chosen);if(!deck.value)return;if(action==='remove')await ElMessageBox.confirm('删除当前页面后可继续编辑其他页，是否删除？','删除页面',{type:'warning'});requireTarget(pid,own,chosen);let command=deckCommands.get(key);if(!command){command={revision:deck.value.deck_revision,key:crypto.randomUUID(),ids:ordered};deckCommands.set(key,command)}const result=action==='insert'?await api.insert(pid,chosen||null,command.revision,command.key):action==='duplicate'?await api.duplicate(pid,chosen,command.revision,command.key):action==='remove'?await api.deleteSlide(pid,chosen,command.revision,command.key):await api.order(pid,command.ids,command.revision,command.key);deckCommands.delete(key);requireTarget(pid,own);const oldIds=new Set(deck.value.slides.map(s=>s.id));deck.value=result;for(const s of result.slides)store.queue(pid,s,commitSlide);selectedId.value=result.slides.find(s=>!oldIds.has(s.id))?.id||result.slides.find(s=>s.id===chosen)?.id||result.slides[0]?.id||'';blockId.value=null;await load(false)}catch(e:any){if(commandErrorStatus(e)===409)deckCommands.delete(key);if(activeTarget(pid,own)&&e!=='cancel'&&e!=='close'&&e.name!=='AbortError')catchError(e)}finally{if(activeTarget(pid,own))busy.value=false}});await actionTail}
async function generation(all=false){const pid=id.value,own=viewGeneration,key=pid+':'+all;busy.value=true;try{await flush();requireTarget(pid,own);if(all)await ElMessageBox.confirm('整份重新生成会覆盖现有页面，包括手工内容；后台会保留原快照。','确认重新生成',{type:'warning'});requireTarget(pid,own);let command=generationCommands.get(key);if(!command){command={key:crypto.randomUUID(),body:{deck_revision:project.value!.deck_revision,regenerate_all:all,overwrite_acknowledged:all}};generationCommands.set(key,command)}await api.generate(pid,command.body,command.key);generationCommands.delete(key);if(!activeTarget(pid,own))return;events.watch(pid,'deck');await load(false)}catch(e:any){if(commandErrorStatus(e)===409)generationCommands.delete(key);if(activeTarget(pid,own)&&e!=='cancel'&&e!=='close'&&e.name!=='AbortError')catchError(e)}finally{if(activeTarget(pid,own))busy.value=false}}
async function cancel(){const pid=id.value,own=viewGeneration;busy.value=true;try{let command=cancelCommands.get(pid);if(!command){const p=await api.project(pid);requireTarget(pid,own);command={key:crypto.randomUUID(),body:{deck_revision:p.deck_revision}};cancelCommands.set(pid,command)}await api.cancel(pid,Number(command.body.deck_revision),command.key);cancelCommands.delete(pid);if(activeTarget(pid,own))await load(false)}catch(e){if(commandErrorStatus(e)===409)cancelCommands.delete(pid);if(activeTarget(pid,own))catchError(e)}finally{if(activeTarget(pid,own))busy.value=false}}
async function retrySlide(){const q=queue.value,pid=id.value,sid=q?.state.slide.id,own=viewGeneration;if(!q||!sid)return;const key=pid+':'+sid;busy.value=true;try{await flush();requireTarget(pid,own,sid);let command=retryCommands.get(key);if(!command){command={key:crypto.randomUUID(),body:{revision:q.state.slide.revision,deck_revision:project.value!.deck_revision}};retryCommands.set(key,command)}await api.retry(pid,sid,Number(command.body.revision),Number(command.body.deck_revision),command.key);retryCommands.delete(key);if(!activeTarget(pid,own,sid))return;events.watch(pid,'deck');await load(false)}catch(e:any){if(commandErrorStatus(e)===409)retryCommands.delete(key);if(activeTarget(pid,own,sid)&&e.name!=='AbortError')catchError(e)}finally{if(activeTarget(pid,own))busy.value=false}}
async function switchLayout(layoutId:string){const pid=id.value;try{await enqueue((s,c)=>api.page(pid,s.id,'put','layout',{revision:s.revision,layout_id:layoutId},c.idempotencyKey))}catch{}}
async function unlock(){const pid=id.value;try{await enqueue((s,c)=>api.page(pid,s.id,'post','unlock-flex',{revision:s.revision},c.idempotencyKey))}catch{}}
async function insertBlock(type:string,columns=1,parentId?:string,index?:number){const q=queue.value,pid=id.value;if(!q)return;try{await enqueue(createBlockInsertion(type,columns,blockId.value,(sid,action,body,key)=>api.page(pid,sid,action==='blocks'?'post':'put',action,body,key),parentId,index,slide=>{q.state.draft=cloneJson(slide)}))}catch{}}
async function removeBlock(){const pid=id.value;if(!selected.value)return;const bid=selected.value.id;try{await enqueue((s,c)=>api.page(pid,s.id,'delete',`blocks/${bid}`,{revision:s.revision},c.idempotencyKey));blockId.value=null}catch{}}
async function image(file:File){const pid=id.value;if(!selected.value)return;const bid=selected.value.id;try{await enqueue((s,c)=>api.image(pid,s.id,bid,file,s.revision,c.idempotencyKey))}catch{}}
function initThemeQueue(p:Project){return store.themeQueue(p,async(pid,body,key)=>{const token=user.token;await store.flush(pid);if(!token||token!==user.token)throw Object.assign(new Error('登录会话已改变'),{name:'AbortError'});return api.theme(pid,body,key)},result=>{if(result.id!==id.value)return;project.value=result;const preview=themePreview.value;if(preview?.project_id===result.id&&preview.theme_id===result.theme_id&&JSON.stringify(preview.theme_overrides||{})===JSON.stringify(result.theme_overrides||{}))themePreview.value=null})}
async function themeChange(value:ThemeDraft,retry=false){const q=themeQueues.get(value.project_id);if(!q)throw new Error('主题草稿所属项目未就绪');if(retry&&['failed','conflict'].includes(q.state.status))q.retry();const latest=q.state.draft||{project_id:q.state.project.id,theme_id:q.state.project.theme_id,theme_overrides:q.state.project.theme_overrides||{}};if(JSON.stringify(latest)!==JSON.stringify(value))void q.enqueue(value).catch(()=>{});try{return await q.flush()}catch(e){if(value.project_id===id.value)catchError(e);throw e}}
async function themeRebase(){const pid=id.value,own=viewGeneration,q=themeQueues.get(pid);if(!q)throw new Error('主题草稿未就绪');await ElMessageBox.confirm('将以最新主题版本重新应用当前微调，预览草稿会保留。','重新应用主题',{type:'warning'});requireTarget(pid,own);const p=await api.project(pid);requireTarget(pid,own);q.retry(p);return q.flush()}
async function proposal(kind:'ai-edit'|'relayout',instruction?:string,history?:{instruction:string;note?:string}[]){const q=queue.value,pid=id.value,sid=q?.state.slide.id,own=viewGeneration;if(!q||!sid)throw new Error('当前页未就绪');await q.flush();if(q!==queue.value||!activeTarget(pid,own,sid))throw new Error('页面已切换，请在当前页重新发起候选');const slide=q.state.slide;const result=await api.proposal(pid,sid,kind,{revision:slide.revision,instruction,history:history?.slice(-5)});requireTarget(pid,own,sid);if('operations' in result||'candidates' in result)return result as Proposal;const controller=new AbortController();controllers.add(controller);try{const finished=await waitTask(result as Task,controller.signal);requireTarget(pid,own,sid);const payload=finished.result as Record<string,unknown>|undefined;const proposalId=String(payload?.proposal_id||(finished as any).proposal_id||'');if(!proposalId)throw new Error('任务未返回候选标识');return await api.getProposal(pid,proposalId)}finally{controllers.delete(controller)}}
async function applyAI(p:Proposal,op:ProposalOperation,side:'before'|'after'){const pid=id.value;await enqueue((s,c)=>api.apply(pid,s.id,'ai-edit',{proposal_id:p.proposal_id||p.id,op_id:op.op_id||op.id,side,revision:s.revision},c.idempotencyKey))}
async function applyLayout(p:Proposal,candidate:string){const pid=id.value;await enqueue((s,c)=>api.apply(pid,s.id,'relayout',{proposal_id:p.proposal_id||p.id,candidate_id:candidate,revision:s.revision},c.idempotencyKey))}
async function restoreLayout(tree:FlexContainer){const pid=id.value;await enqueue((s,c)=>api.page(pid,s.id,'put','flex-layout',{revision:s.revision,layout_tree:tree},c.idempotencyKey))}
async function history(direction:'undo'|'redo'){const q=queue.value,pid=id.value,own=viewGeneration;if(!q||disabled.value)return;try{await q.navigateHistory(direction,(s,snapshot,c)=>api.page(pid,s.id,'put','flex-state',{revision:s.revision,layout_mode:snapshot.layout_mode,layout_id:snapshot.layout_id,blocks:snapshot.blocks,layout_tree:snapshot.layout_tree||null},c.idempotencyKey))}catch(e){if(activeTarget(pid,own))catchError(e)}}
async function recover(rebase:boolean,discard=false){const q=queue.value,pid=id.value,own=viewGeneration,sid=q?.state.slide.id;if(!q||!sid)return;try{if(discard)await ElMessageBox.confirm('确认放弃未保存操作？正式内容将重新读取。','放弃草稿',{type:'warning'});requireTarget(pid,own,sid);const d=await api.deck(pid);requireTarget(pid,own,sid);const server=d.slides.find(s=>s.id===sid);if(!server)throw new Error('页面已删除，草稿可复制保存');if(discard)q.discard(server);else if(rebase){await ElMessageBox.confirm('将以服务器最新版本重新应用本地操作，请先核对或复制草稿。','重新应用',{type:'warning'});requireTarget(pid,own,sid);q.retry(server)}else q.retry();error.value=''}catch(e:any){if(activeTarget(pid,own,sid)&&e!=='cancel'&&e!=='close'&&e.name!=='AbortError')catchError(e)}}
function copyDraft(){draftText.value=JSON.stringify(queue.value?.state.draft||queue.value?.state.slide,null,2);draftDialog.value=true}
function groupPreset(preset:GroupPreset|null){if(!current.value?.layout_tree||!parent.value)return;const next=setContainerPreset(current.value.layout_tree,parent.value.parent.id,preset);if(next)layoutTree(next)}
function leafValue(key:string,value:unknown){if(!current.value?.layout_tree||!blockId.value)return;const next=cloneJson(current.value.layout_tree),loc=findLeafParent(next,blockId.value);if(loc){(loc.leaf as any)[key]=value;layoutTree(next)}}
function gap(value:number|undefined){if(!current.value?.layout_tree||!parent.value)return;const tree=cloneJson(current.value.layout_tree),node=findContainerById(tree,parent.value.parent.id);if(node){node.gap_pt=value||0;layoutTree(tree)}}
function moveBlock(d:number){if(!current.value?.layout_tree||!blockId.value||!parent.value)return;const loc=parent.value,to=Math.max(0,Math.min(loc.parent.children.length,loc.index+(d>0?2:-1))),next=moveLeaf(current.value.layout_tree,blockId.value,loc.parent.id,to);if(next)layoutTree(next)}
function dimension(axis:'x'|'y'){return current.value?.layout_tree&&blockId.value?Math.round(leafDimensionPercent(current.value.layout_tree,blockId.value,axis)*100)/100:100}
function changeDimension(axis:'x'|'y',value:number|undefined){if(value==null||!current.value?.layout_tree||!blockId.value)return;const next=setLeafDimensionPercent(current.value.layout_tree,blockId.value,axis,value);if(next)layoutTree(next)}
async function leave(){try{await flush();return true}catch{try{await ElMessageBox.confirm('尚有未保存内容或版本冲突，草稿会留在当前会话。关闭浏览器或退出账号前请复制草稿。','保留编辑',{confirmButtonText:'保留草稿并离开',cancelButtonText:'继续编辑'});return true}catch{return false}}}
function unload(e:BeforeUnloadEvent){if(store.dirty(id.value)||themePanel.value?.isDirty()||themeQueue.value?.state.pending){e.preventDefault();e.returnValue=''}}
function keyboard(e:KeyboardEvent){if(!alive||present.value)return;if(e.key==='Escape'&&blockId.value){e.preventDefault();if(document.activeElement instanceof HTMLElement)document.activeElement.blur();blockId.value=null;previewTree.value=null;return}const target=e.target as HTMLElement|null;if(target?.isContentEditable||target&&['INPUT','TEXTAREA','SELECT'].includes(target.tagName))return;const command=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(command&&(key==='z'||key==='y')){e.preventDefault();void history(key==='y'||e.shiftKey?'redo':'undo')}else if(!command&&!e.altKey&&['Delete','Backspace'].includes(e.key)&&current.value?.layout_mode==='flex'&&blockId.value&&!disabled.value&&current.value.blocks.length>1){e.preventDefault();void removeBlock()}}
function locate(issue:Issue){if(issue.slide_id){void choose(issue.slide_id);blockId.value=issue.block_id||issue.slot_id||null;exportOpen.value=false}}
watch(()=>user.token,(token,previous)=>{if(!token||previous&&token!==previous){viewGeneration++;loadGeneration++;selectionGeneration++;clearTimeout(refreshTimer);busy.value=false;store.clear();generationCommands.clear();retryCommands.clear();cancelCommands.clear();deckCommands.clear();themeQueues.forEach(q=>q.dispose());themeQueues.clear();themePreview.value=null;draftText.value='';draftDialog.value=false;project.value=null;deck.value=null;events.stop();controllers.forEach(c=>c.abort())}})
watch(id,()=>{viewGeneration++;selectionGeneration++;busy.value=false;events.stop();events.task.value=null;selectedId.value='';blockId.value=null;previewTree.value=null;themePreview.value=null;project.value=null;deck.value=null;void load()})
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onMounted(()=>{removeGuard=addCloseGuard(route.path,leave);window.addEventListener('beforeunload',unload);window.addEventListener('keydown',keyboard);void load()});onActivated(()=>{const returning=!alive;alive=true;if(returning){if(generating.value)events.reconnect();void load(false)}});onDeactivated(()=>{alive=false;events.stop()});onBeforeUnmount(()=>{alive=false;removeGuard?.();clearTimeout(refreshTimer);controllers.forEach(c=>c.abort());window.removeEventListener('beforeunload',unload);window.removeEventListener('keydown',keyboard)})
</script>
<template><div class="app-container workbench" v-loading="loading"><el-alert v-if="error" type="error" :title="error" closable @close="error=''"><el-button @click="load()">重新读取</el-button></el-alert><template v-if="project&&deck&&theme"><header class="editor-heading"><div><h2>{{project.title}}</h2><small>{{deck.slides.filter(s=>s.status==='ready').length}} / {{deck.total??deck.slides.length}}页就绪 · {{deck.slides.filter(s=>s.status==='failed').length}}页失败 · {{project.status}} · <span aria-live="polite">{{saveLabel}}</span></small></div><el-button @click="router.push({path:'/aippt/detail',query:{projectId:id}})">材料与提纲</el-button><el-button v-if="!generating" v-hasPermi="['aippt:deck:generate']" :disabled="busy" type="primary" @click="generation(false)">生成 / 续跑</el-button><el-button v-if="!generating&&deck.slides.length" v-hasPermi="['aippt:deck:generate']" :disabled="busy" @click="generation(true)">整份重做</el-button><el-button v-if="generating" v-hasPermi="['aippt:deck:cancel']" :loading="busy" type="warning" @click="cancel">取消待生成页</el-button><el-button v-hasPermi="['aippt:export:check']" :disabled="generating||!deck.slides.length" @click="exportOpen=true">质量与导出</el-button><el-button :disabled="!deck.slides.some(s=>s.status==='ready')" @click="present=true">放映</el-button></header>
<el-alert v-if="generating" title="正在逐页生成，完成页面会即时显示；生成结束后可以编辑。取消将保留已完成页和在途结果。" type="info" :closable="false"/><el-alert v-if="events.deliveryMessage?.value" :title="events.deliveryMessage.value" :type="events.delivery?.value?.status==='degraded'?'warning':'info'" :closable="false"/><el-alert v-if="events.disconnected.value" :title="events.error.value||'进度连接中断，正在恢复快照'" type="warning" :closable="false"><el-button @click="events.reconnect">恢复进度连接</el-button></el-alert><RecoveryBanner v-if="queue" :queue="queue" @copy="copyDraft" @retry="recover(false)" @rebase="recover(true)" @discard="recover(false,true)"/>
<div class="compact-tools"><el-button @click="filmstripOpen=!filmstripOpen">{{filmstripOpen?'收起页面列表':'展开页面列表'}}</el-button><el-button @click="inspectorOpen=!inspectorOpen">{{inspectorOpen?'收起编辑面板':'展开编辑面板'}}</el-button></div><div class="workspace" :class="{'filmstrip-collapsed':!filmstripOpen,'inspector-collapsed':!inspectorOpen}"><Filmstrip v-show="filmstripOpen" :slides="deck.slides" :theme="theme" :selected="selectedId" :disabled="disabled" @select="choose" @insert="pageAction('insert')" @duplicate="pageAction('duplicate')" @remove="pageAction('remove')" @order="ids=>pageAction('order',ids)"/>
<main class="canvas-region"><div class="canvas-tools"><el-button size="small" :disabled="disabled||!queue?.state.history.length" @click="history('undo')">撤销</el-button><el-button size="small" :disabled="disabled||!queue?.state.future.length" @click="history('redo')">重做</el-button><label>缩放 <el-input-number v-model="zoom" :min="40" :max="160" :step="10" size="small"/>%</label><el-button size="small" :disabled="busy||generating||!current||!checkPermi(['aippt:deck:generate'])" @click="retrySlide">重试当前页</el-button></div><div class="canvas-scroll"><div v-if="viewSlide&&viewSlide.blocks.length" class="canvas-wrap" :style="{width:zoom+'%',minWidth:zoom+'%'}"><SlideStage :slide="viewSlide" :theme="theme" :index="deck.slides.findIndex(s=>s.id===selectedId)" :editable="!disabled&&current?.status==='ready'" :selected="blockId" reveal @select="blockId=$event" @commit="content"><FlexEditLayer v-if="viewSlide.layout_mode==='flex'&&viewSlide.layout_tree" :tree="viewSlide.layout_tree" :selected="blockId" :disabled="disabled||current?.status!=='ready'" @preview="previewTree=$event" @commit="layoutTree" @insert="(t,p,i,c)=>insertBlock(t,c,p,i)"/></SlideStage></div><el-empty v-else :description="current?.status==='failed'?'该页生成失败，可重试或续跑':'先确认提纲，再生成页面；也可插入空白页开始编辑'"/></div><div v-if="current?.issues?.length" class="page-issues"><el-alert v-for="(issue,i) in current.issues" :key="i" :title="issue.message" :type="issue.severity==='error'?'error':'warning'" :closable="false"/></div></main>
<aside v-show="inspectorOpen" class="inspector"><el-tabs v-model="tab"><el-tab-pane label="内容" name="content"><template v-if="selected"><ElementToolbar :block="selected" :theme="theme" :disabled="disabled" @change="style" @content="fullContent"/><ChartDataEditor v-if="selected.type==='chart'" :block="selected" :disabled="disabled" @change="fullContent"/><ImagePanel v-if="selected.type==='image'" :block="selected" :disabled="disabled||!canImage" @upload="image"/><template v-if="current?.layout_tree&&parent"><h4>灵活容器</h4><p>列宽、行高可用键盘输入，按最近对应容器的比例调整。</p><el-form label-width="85px" :disabled="disabled"><el-form-item label="列宽（%）"><el-input-number :model-value="dimension('x')" :min="5" :max="100" :precision="2" aria-label="列宽百分比" @change="(v:any)=>changeDimension('x',v)"/></el-form-item><el-form-item label="行高（%）"><el-input-number :model-value="dimension('y')" :min="5" :max="100" :precision="2" aria-label="行高百分比" @change="(v:any)=>changeDimension('y',v)"/></el-form-item><el-form-item label="留白间距"><el-input-number :model-value="parent.parent.gap_pt||0" :min="0" :max="96" @change="gap"/></el-form-item><el-form-item label="容器皮肤"><el-select :model-value="parent.parent.preset||''" @change="(v:any)=>groupPreset(v||null)"><el-option label="无" value=""/><el-option v-for="(label,v) in {solid_boxes:'实色卡片',outline_boxes:'描边卡片',side_line:'侧线',numbered_steps:'编号步骤',timeline:'时间线'}" :key="v" :label="label" :value="v"/></el-select></el-form-item><el-form-item v-if="selected.type==='image'||selected.type==='chart'" label="贴边出血"><el-switch :model-value="!!parent.leaf.bleed" @change="(v:any)=>leafValue('bleed',v)"/></el-form-item><el-form-item label="横向偏移"><el-input-number :model-value="parent.leaf.offset_x_pt||0" :min="-960" :max="960" @change="(v:any)=>leafValue('offset_x_pt',v)"/></el-form-item><el-form-item label="纵向偏移"><el-input-number :model-value="parent.leaf.offset_y_pt||0" :min="-960" :max="960" @change="(v:any)=>leafValue('offset_y_pt',v)"/></el-form-item><el-button @click="moveBlock(-1)">块上移</el-button><el-button @click="moveBlock(1)">块下移</el-button><el-button type="danger" :disabled="current.blocks.length<=1" @click="removeBlock">删除块</el-button></el-form></template><el-divider/></template><el-empty v-else description="点击画布选择内容；文字可直接编辑"/><BlockInsertRail v-if="current?.layout_mode==='flex'" :disabled="disabled" @insert="insertBlock"/></el-tab-pane><el-tab-pane label="主题" name="theme"><ThemePanel v-if="themeProject" ref="themePanel" :project="themeProject" :disabled="busy||generating||!canTheme" :save="themeChange" :rebase="themeRebase" :status="themeQueue?.state.status" :save-error="themeQueue?.state.error" @preview="value=>themePreview=value"/></el-tab-pane><el-tab-pane label="布局" name="layout"><template v-if="current"><LayoutPanel :project-id="id" :slide="current" :disabled="disabled" @switch="switchLayout" @unlock="unlock"/><el-divider/><RelayoutPanel :slide="current" :theme="theme" :disabled="busy||generating||!canAI" :can-apply="canEdit" :request="()=>proposal('relayout')" :apply="applyLayout" :restore="restoreLayout"/></template></el-tab-pane><el-tab-pane label="AI修改" name="ai"><AiEditPanel v-if="current" :slide="current" :disabled="busy||generating||!canAI" :can-apply="canEdit" :request="(i,h)=>proposal('ai-edit',i,h)" :apply="applyAI"/></el-tab-pane></el-tabs></aside></div>
<ExportDrawer v-model="exportOpen" :project-id="id" :title="project.title" :deck-revision="project.deck_revision" :theme-revision="project.theme_revision" :flush="flush" @locate="locate"/><PresentOverlay v-if="present" :slides="deck.slides.filter(s=>s.status==='ready')" :theme="theme" :start="Math.max(0,deck.slides.filter(s=>s.status==='ready').findIndex(s=>s.id===selectedId))" @close="index=>{selectedId=deck!.slides.filter(s=>s.status==='ready')[index]?.id||selectedId;present=false}"/>
<el-dialog v-model="draftDialog" title="复制本地草稿" width="min(800px,95vw)"><p>此内容只保留在当前登录会话。复制后可核对或重新应用，不能当作正式保存结果。</p><el-input v-model="draftText" type="textarea" :rows="18" readonly/><template #footer><el-button @click="draftDialog=false">关闭</el-button></template></el-dialog></template></div></template>
<style scoped>.workbench{padding:18px;min-width:0}.editor-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:16px}.editor-heading>div:first-child{margin-right:auto}.editor-heading h2{margin:0 0 8px;font-size:22px}.editor-heading small{color:#606266}.editor-heading .el-button{margin:0}.workspace{display:grid;grid-template-columns:190px minmax(280px,1fr) 320px;gap:14px;margin-top:16px;min-width:0}.canvas-region{min-width:0;background:#f2f4f8;border-radius:8px;padding:14px}.canvas-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.canvas-tools .el-button{margin:0}.canvas-tools label{display:flex;align-items:center;gap:6px}.canvas-scroll{overflow:auto;min-height:300px;padding:24px 16px 48px}.canvas-wrap{box-shadow:0 8px 24px #16243c1a;min-width:0}.inspector{background:#fff;border:1px solid #ebeef5;border-radius:8px;padding:14px;min-width:0;max-height:calc(100vh - 260px);overflow:auto}.page-issues{display:grid;gap:8px;margin-top:12px}.el-alert{margin-bottom:10px}.el-select{width:100%}@media(max-width:1280px){.workspace{grid-template-columns:150px minmax(280px,1fr) 280px}.workbench{padding:12px}.inspector{padding:10px}}@media(max-width:1024px){.workspace{grid-template-columns:130px minmax(280px,1fr)}.inspector{grid-column:1/-1;max-height:none}.canvas-scroll{padding:20px 12px 40px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
 .compact-tools{display:none}.workspace.filmstrip-collapsed{grid-template-columns:minmax(280px,1fr) 320px}.workspace.inspector-collapsed{grid-template-columns:190px minmax(280px,1fr)}.workspace.filmstrip-collapsed.inspector-collapsed{grid-template-columns:minmax(280px,1fr)}@media(max-width:1280px){.workspace.filmstrip-collapsed{grid-template-columns:minmax(280px,1fr) 280px}.workspace.inspector-collapsed{grid-template-columns:150px minmax(280px,1fr)}}@media(max-width:1024px){.compact-tools{display:flex;gap:8px;margin-top:12px}.workspace.filmstrip-collapsed,.workspace.filmstrip-collapsed.inspector-collapsed{grid-template-columns:minmax(280px,1fr)}.workspace.inspector-collapsed{grid-template-columns:130px minmax(280px,1fr)}.workspace .inspector{grid-column:1/-1}} </style>







